import assert from 'node:assert';
import { load, dump, YAML11_SCHEMA } from 'js-yaml';

describe('proof', () => {
  it('fails on the patched build', () => {
    // YAML 1.1 implicit integers: signed non-decimal forms must keep sign and radix
    assert.strictEqual(load('-010\n', { schema: YAML11_SCHEMA }), -8);
    assert.strictEqual(load('-0x10\n', { schema: YAML11_SCHEMA }), -16);
    assert.strictEqual(load('+0x10\n', { schema: YAML11_SCHEMA }), 16);
    assert.strictEqual(load('-0b101\n', { schema: YAML11_SCHEMA }), -5);
    assert.strictEqual(load('-1:30\n', { schema: YAML11_SCHEMA }), -90);
  });
});
"}, "note": "Emptying the sign branch in parseYamlInteger breaks the YAML 1.1 int tag for signed non-decimal literals: '-010' now loads as -10 instead of -8, '-0x10' as -0 instead of -16, and '-1:30' as -30 instead of -90, since the sign is neither stripped nor applied."}
